type ContainerListState = "active" | "degraded" | "provisioning" | "ready";

/**
 * Derive a container's high-level state from the per-instance health counters.
 * Priority: degraded (any failed) > provisioning (any starting/scheduling) >
 * active (any active) > ready.
 */
function deriveContainerState(app: DashApplication): ContainerListState {
	const { failed, starting, scheduling, active } = app.health.instances;
	if (failed > 0) {
		return "degraded";
	}
	if (starting > 0 || scheduling > 0) {
		return "provisioning";
	}
	if (active > 0) {
		return "active";
	}
	return "ready";
}

function containerToJsonRow(app: DashApplication) {
	return {
		id: app.id,
		name: app.name,
		state: deriveContainerState(app),
		instances: app.instances,
		image: app.image,
		version: app.version,
		updated_at: app.updated_at,
		created_at: app.created_at,
	};
}

function renderContainersTable(applications: DashApplication[]): void {
	logger.table(
		applications.map((app) => ({
			ID: app.id,
			NAME: app.name,
			STATE: deriveContainerState(app),
			"LIVE INSTANCES": String(app.instances),
			"LAST MODIFIED": app.updated_at,
		}))
	);
}

